package com.rotarypumpers.meraki;
import android.app.*;import android.content.*;import android.net.Uri;import android.widget.*;import org.json.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;import java.nio.charset.StandardCharsets;import java.io.*;import com.rotarypumpers.meraki.core.*;
/** Manual Visualizer uploads and optional Visualizer JSON export. No other app integration. */
final class VisualizerController {
 private volatile JSONObject pendingShot;
 private AlertDialog working;
 private final Activity a;private final VisualizerVault vault;private final VisualizerJobs jobs;private final VisualizerHttp http;
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final AtomicBoolean busy=new AtomicBoolean();
 private final java.util.function.BooleanSupplier allowed;private final VisualizerSession session;
 VisualizerController(Activity a,java.util.function.BooleanSupplier allowed){this(a,allowed,new VisualizerHttp());}
 VisualizerController(Activity a,java.util.function.BooleanSupplier allowed,VisualizerHttp http){
  this.http=http;this.a=a;this.allowed=allowed;vault=new VisualizerVault(a);jobs=new VisualizerJobs(a.getFilesDir());
  session=new VisualizerSession(http,new VisualizerSession.Store(){public JSONObject load()throws Exception{return vault.read("tokens");}public void save(JSONObject t)throws Exception{vault.save("tokens",t);}});
  // Retire obsolete staged sharing files once, without touching journal, recipes, pairing or upload receipts.
  android.content.SharedPreferences prefs=a.getSharedPreferences("visualizer_cleanup",Context.MODE_PRIVATE);
  if(!prefs.getBoolean("retired_sharing_v1",false)){try{vault.save("export",null);LegacyShareCleanup.run(a.getFilesDir(),a.getCacheDir());prefs.edit().putBoolean("retired_sharing_v1",true).apply();}catch(Exception ignored){}}
 }
 private long now(){return System.currentTimeMillis()/1000;}
 private void ui(Runnable r){a.runOnUiThread(()->{if(!a.isFinishing()&&!a.isDestroyed())r.run();});}
 private void message(String title,String text){ui(()->LightDialogs.builder(a).setTitle(title).setMessage(text).setPositiveButton("Close",null).show());}
 private void menu(String title,String detail,String[] labels,java.util.function.IntConsumer action){
  LinearLayout rows=new LinearLayout(a);rows.setOrientation(1);int pad=(int)(16*a.getResources().getDisplayMetrics().density);rows.setPadding(pad,pad,pad,pad);
  TextView description=new TextView(a);description.setText(detail);description.setTextSize(14);description.setPadding(0,0,0,pad);rows.addView(description);
  final AlertDialog[] dialog=new AlertDialog[1];
  for(int i=0;i<labels.length;i++){final int which=i;Button b=new Button(a);b.setText(labels[i]);b.setAllCaps(false);b.setOnClickListener(v->{dialog[0].dismiss();action.accept(which);});rows.addView(b,new LinearLayout.LayoutParams(-1,-2));}
  ScrollView scroll=new ScrollView(a);scroll.addView(rows);dialog[0]=LightDialogs.builder(a).setTitle(title).setView(scroll).setNegativeButton("Close",null).create();dialog[0].show();
 }
 private void progress(String label){ui(()->{if(working!=null){working.setMessage(label);return;}LinearLayout view=new LinearLayout(a);view.setPadding(24,24,24,24);view.setGravity(android.view.Gravity.CENTER);view.addView(new ProgressBar(a));working=LightDialogs.builder(a).setTitle("Visualizer").setMessage(label).setView(view).create();working.setCancelable(false);working.setCanceledOnTouchOutside(false);working.show();});}
 private void work(Runnable task){if(!allowed.getAsBoolean()){message("Finish the current task","Disconnect recording and wait for machine settings to finish before uploading.");return;}if(!busy.compareAndSet(false,true)){message("Visualizer","Please wait for the current request.");return;}progress("Please wait…");worker.execute(()->{try{task.run();}finally{busy.set(false);ui(()->{if(working!=null){working.dismiss();working=null;}});}});}
 void settings(){if(!allowed.getAsBoolean()){message("Finish the current task","Disconnect recording before opening Visualizer sign-in.");return;}try{JSONObject t=vault.read("tokens");menu("Visualizer",(t==null?"Connect Visualizer to upload shots.":"Connected to "+t.optString("account_name","Visualizer")+".")+"\nUploads are manual; nothing is shared automatically.",new String[]{t==null?"Connect Visualizer":"Reconnect Visualizer","Visualizer help","Disconnect Visualizer"},w->{if(w==0){pendingShot=null;connect();}else if(w==1)instructions();else disconnect();});}catch(Exception e){message("Visualizer","Sign-in could not be read. Reconnect your Visualizer account; machine pairing is unchanged.");}}
 private void instructions(){message("Visualizer","Open Shots, choose a completed shot and tap Visualizer. Choose Upload to Visualizer, then confirm. After upload, tap View in Visualizer.\n\nYour recorded weight curve, scale-derived flow and available shot settings are included. Pressure and temperature sensor curves are omitted because they are not measured. Written tasting notes are optional.\n\nSign in through your browser. Companion uses PKCE and never asks for your Visualizer password.\n\nSave Visualizer JSON is an optional file export. Accepted uploads are reused; an uncertain upload must be checked in your Visualizer account before another attempt.");}
 private void connect(){
  if(BuildConfig.VISUALIZER_CLIENT_ID.isEmpty()){
   pendingShot=null;
   message("Visualizer setup required","This build needs a Visualizer OAuth client ID for sign-in. You can still export Visualizer JSON.");
   return;
  }
  LightDialogs.builder(a).setTitle("Connect Visualizer").setMessage("Continue to Visualizer in your browser to sign in and approve Meraki Companion. No shot will be uploaded during sign-in.").setNegativeButton("Cancel",(d,w)->pendingShot=null).setPositiveButton("Continue",(d,w)->{try{JSONObject p=VisualizerOAuth.begin(BuildConfig.VISUALIZER_CLIENT_ID,now());vault.save("pending",p);a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(VisualizerOAuth.authorization(p))));}catch(Exception e){message("Visualizer sign-in","Could not open your browser. Check that a browser is available, then try again.");}}).show();}
 void callback(Intent intent){Uri data=intent.getData();if(data==null)return;String value=data.toString();intent.setData(null);work(()->{try{JSONObject p=vault.read("pending");String code=VisualizerOAuth.callback(value,p,now());vault.save("pending",null);JSONObject t=VisualizerOAuth.tokens(http.exchange(VisualizerOAuth.codeForm(p,code)),p.getString("client_id"),now());JSONObject account=http.account(t.getString("access_token"));t.put("account_id",account.getString("id")).put("account_name",account.optString("name","Visualizer"));vault.save("tokens",t);JSONObject resume=pendingShot;pendingShot=null;if(resume!=null)ui(()->preview(resume));else message("Visualizer connected","Open a shot and tap Visualizer. Nothing has been uploaded.");}catch(Exception e){try{vault.save("pending",null);}catch(Exception ignored){}pendingShot=null;message("Visualizer sign-in","Sign-in did not finish. Check OAuth registration and try connecting again. No shot was uploaded.");}});}
 private JSONObject token()throws Exception{return session.valid(now());}
 private void disconnect(){work(()->{try{JSONObject t=vault.read("tokens");vault.save("tokens",null);vault.save("pending",null);if(t!=null){try{http.revoke(t.getString("client_id"),t.getString("access_token"));http.revoke(t.getString("client_id"),t.getString("refresh_token"));}catch(Exception e){message("Disconnected on this phone","Local sign-in was removed. Remote revocation was not confirmed; you can revoke Companion in Visualizer's authorized applications.");return;}}message("Visualizer disconnected","Machine pairing and your shot journal are unchanged.");}catch(Exception e){message("Visualizer","Could not clear sign-in; try again.");}});}
 void share(JSONObject shot){
  if(!allowed.getAsBoolean()){message("Finish recording first","Disconnect recording before uploading this shot.");return;}
  try{JSONObject payload=VisualizerExport.build(shot,false,null);JSONObject stable=new JSONObject(shot.toString());JSONObject t=vault.read("tokens");
   JSONObject previous=t==null?null:jobs.get(t.getString("account_id"),shot.optString("start_utc"));
   if(previous!=null&&"uploaded".equals(previous.optString("state"))){receipt(previous.getString("id"),payload);return;}
   if(previous!=null&&("sending".equals(previous.optString("state"))||"uncertain".equals(previous.optString("state")))){uncertain(t.getString("account_id"),shot.optString("start_utc"));return;}
   menu("Visualizer","Upload the recorded graph and shot settings to Visualizer, or save a Visualizer JSON file.",new String[]{t==null?"Connect & upload":"Upload to Visualizer","Save Visualizer JSON"},w->{if(w==0)startUpload(stable);else export(payload);});
  }catch(Exception e){message("Shot cannot be uploaded",e.getMessage());}
 }
 private void startUpload(JSONObject shot){try{if(vault.read("tokens")==null){pendingShot=shot;connect();}else preview(shot);}catch(Exception e){message("Visualizer","Reconnect Visualizer before uploading.");}}
 private void preview(JSONObject shot){CheckBox notes=new CheckBox(a);notes.setText("Include my written tasting note");notes.setChecked(false);LightDialogs.builder(a).setTitle("Upload this shot?").setMessage("Uploads the recorded graph and shot settings to Visualizer. Its account rules control online visibility. Nothing uploads without confirmation.").setView(notes).setNegativeButton("Cancel",null).setPositiveButton("Upload",(d,w)->upload(shot,notes.isChecked())).show();}
 private void upload(JSONObject shot,boolean notes){work(()->{String account=null,local=shot.optString("start_utc");boolean began=false;try{JSONObject t=token();account=t.getString("account_id");JSONObject previous=jobs.get(account,local);String state=previous.getString("state");if("uploaded".equals(state)){receipt(previous.getString("id"),VisualizerExport.build(shot,false,null));return;}if("sending".equals(state)||"uncertain".equals(state)){uncertain(account,local);return;}JSONObject payload=VisualizerExport.build(shot,notes,null);if(!jobs.begin(account,local))throw new IOException("An upload is already recorded for this shot");began=true;progress("Uploading graph and shot settings…");String id=http.upload(t.getString("access_token"),payload);jobs.accepted(account,local,id);receipt(id,payload);}catch(Exception e){if(began)try{jobs.failure(account,local,e);}catch(Exception ignored){}message("Visualizer upload",began&&!(e instanceof VisualizerHttp.Rejected&&((VisualizerHttp.Rejected)e).status<500)?"The result is uncertain. Check Visualizer before another attempt; Companion will not upload it again automatically.":e instanceof VisualizerHttp.Rejected?e.getMessage():"Upload could not start. Check your connection and Visualizer sign-in.");}});}
 private void receipt(String id,JSONObject payload){ui(()->menu("Uploaded to Visualizer","Your shot settings and graph are saved on Visualizer. This accepted upload will not be sent again.",new String[]{"View in Visualizer","Save Visualizer JSON"},w->{if(w==0){try{VisualizerExport.requireId(id);a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://visualizer.coffee/shots/"+id)));}catch(Exception e){message("Visualizer","Could not open the shot in your browser.");}}else export(payload);}));}
 private void uncertain(String account,String local){ui(()->LightDialogs.builder(a).setTitle("Check the previous upload").setMessage("A previous request has no confirmed receipt. Look in your Visualizer account first. Only enable another attempt if you have confirmed that the shot is absent.").setNegativeButton("Close",null).setPositiveButton("I checked; shot is absent",(d,w)->work(()->{try{jobs.checkedMissing(account,local);message("Another attempt enabled","Open Visualizer again when ready. No request was sent.");}catch(Exception e){message("Visualizer","Could not update the upload record.");}})).show());}
 private void export(JSONObject payload){try{vault.save("export",payload);a.startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json").putExtra(Intent.EXTRA_TITLE,"Meraki-Visualizer-shot.json"),61);}catch(Exception e){message("Visualizer export","Could not prepare the file.");}}
 boolean fileResult(int request,int result,Intent intent){if(request!=61)return false;if(result!=Activity.RESULT_OK||intent==null||intent.getData()==null){try{vault.save("export",null);}catch(Exception ignored){}return true;}worker.execute(()->{try{JSONObject p=vault.read("export");if(p==null)throw new IOException();try(OutputStream out=a.getContentResolver().openOutputStream(intent.getData())){if(out==null)throw new IOException();out.write(p.toString().getBytes(StandardCharsets.UTF_8));}vault.save("export",null);message("Visualizer JSON saved","The file contains the shot settings and recorded graph for Visualizer.");}catch(Exception e){message("Visualizer export failed","The file could not be saved. Try again with a writable destination.");}});return true;}
 void destroy(){if(working!=null){working.dismiss();working=null;}worker.shutdown();}
}
